{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C21", "C23", "C02", "C03", "C20", "C25", "C26", "C37", "C49", "C52"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C21", "C23", "C02", "C20"],
  "claims": [
    {
      "claim": "Ketanserin, the closest structural context sharing the 4-fluorobenzoyl-piperidine and cyclic-urea pharmacophore, has absolute oral bioavailability of 49.3 ± 18% (range 27 to 69%) by the AUC method and 60% by F = 1 − E after 40 mg oral tablets in fasted subjects; both estimates exceed the 20% threshold.",
      "card_ids": ["C21", "C23"]
    },
    {
      "claim": "Sertindole, a piperidine and fluorophenyl cyclic-urea analogue, has oral bioavailability of approximately 74 to 75% in humans with little effect from food; L2 records confirm about 75% and near-unity tablet-to-solution relative bioavailability.",
      "card_ids": ["C02", "C11", "C24", "C26", "C37"]
    },
    {
      "claim": "Trazodone, an N-alkylated halophenyl heterocycle with a propyl linker, has absolute oral bioavailability of 63 to 91% across fasted and fed populations; L2 records confirm 63 to 91% fasted and 63 to 65% fed.",
      "card_ids": ["C03", "C04", "C19", "C49", "C52"]
    },
    {
      "claim": "Maraviroc, structurally less similar, has fasted F of 24% at 100 mg, still above the 20% threshold; L2 records confirm dose-dependent fasted bioavailability of 24% at 100 mg rising to 33% at 600 mg.",
      "card_ids": ["C20", "C25", "C48"]
    },
    {
      "claim": "Setipiprant, a related CRTh2 antagonist, has human oral bioavailability of at least 50% with L2 records showing 44% in rats and 55% in dogs, providing additional context that related structures exceed the threshold.",
      "card_ids": ["C18", "C28", "C34"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C25", "C26", "C28", "C34", "C37", "C49", "C52"]
    }
  ],
  "evidence_gaps": [
    "No direct F measurement for the exact query molecule; prediction relies on analogue transfer, chiefly ketanserin.",
    "Query is always ionized at physiological pH with logD -0.76 and neutral fraction 0, and no transporter, efflux, or first-pass data are available.",
    "Ketanserin data are for 40 mg tablets in fasted subjects; formulation and dose effects for the query are unknown.",
    "No human PK or metabolic stability data for the query."
  ],
  "decision_summary": "High is retained and strengthened. The closest L1 context, ketanserin, reports absolute F of about 49 to 60%, and related piperidine and fluorophenyl cyclic-urea contexts report F of 74 to 75% (sertindole) and 63 to 91% (trazodone), while the lowest related value, maraviroc at 24%, still exceeds 20%. All newly added L2 records are consistent with their L1 contexts and none provide affirmative evidence for F below 20%. The unfavorable passive-permeability prior is an uncertainty, not evidence for a low outcome."
}

